#include <Servo.h>

Servo myServo; // Создаём объект для управления сервоприводом
int buttonPin = 2; // Пин кнопки (например, D2)
int targetAngle = 90; // Целевой угол (нейтральное положение)

void setup() {
  myServo.attach(4);
  pinMode(buttonPin, INPUT); // Настраиваем пин кнопки как вход
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(buttonPin)) {
    // Плавно поворачиваем к targetAngle с задержкой для стабилизации
    int currentAngle = myServo.read();
    int delta = targetAngle - currentAngle;
    if (delta > 15) { // Избегаем резких рывков
      myServo.write(currentAngle + 1);
      delay(15);
    } else if (delta < -15) {
      myServo.write(currentAngle - 1);
      delay(15);
    } else {
      // Останавливаем мотор, если кнопка удерживается
      myServo.write(targetAngle);
    }
  }
}
